window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca4fadad7ab649f1"]={"versions": [{"id": "FIG-ca4fadad7ab649f1", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilprozesses innerhalb des AUTOSAR E2E-Protokolls (End-to-End Communication Protection Library). Das Diagramm visualisiert den atomaren Teilschritt „Read DataID“ der Prüffunktion <code>E2E_P04Check()</code>, die zur Laufzeit empfangene Datenpakete nach E2E-Profil 4 validiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aufrufer: Prüffunktion <code>E2E_P04Check()</code>, gekennzeichnet durch ein Aktivitäts-Symbol (UML Activity Symbol).\n</li><li>Datenstruktur / Eingangsarray: Byte-Array <code>Data[]</code> (Nutzdaten/Nachrichtenpuffer) ab dem konfigurierbaren Offset <code>Offset</code>.\n</li><li>Zielvariable: Lokale Variable <code>ReceivedDataID</code> vom Datentyp <code>uint32</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node), eine ausführende Aktion (Action) und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Ausführung beginnt am initialen Startknoten.\n</li><li>Der Kontrollfluss geht über in die Aktion: Es werden 4 zusammenhängende Bytes aus dem Datenstrom <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Variable <code>ReceivedDataID</code> kopiert.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Ablauf den Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe gemäß <code>[PRS_E2E_00359]</code>: Implementierungen von <code>E2E_P04Check()</code> müssen die DataID exakt an den Bytepositionen <code>Offset + 4</code> bis <code>Offset + 7</code> im Big-Endian-Format deserialisieren.\n</li><li>Entwickler müssen sicherstellen, dass der Puffer <code>Data[]</code> mindestens eine Größe von <code>Offset + 8</code> Bytes aufweist, um Out-of-Bounds-Zugriffe zu vermeiden, und dass plattformabhängige Endianness-Konvertierungen (z. B. auf Little-Endian-Mikrocontrollern) beim Zusammensetzen des 32-Bit-Wertes berücksichtigt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c16c0f88bb6c223a", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilprozesses innerhalb des AUTOSAR E2E-Protokolls (End-to-End Communication Protection Library). Das Diagramm visualisiert den atomaren Teilschritt „Read DataID“ der Prüffunktion <code>E2E_P04Check()</code>, die zur Laufzeit empfangene Datenpakete nach E2E-Profil 4 validiert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext/Aufrufer: Prüffunktion <code>E2E_P04Check()</code>, gekennzeichnet durch ein Aktivitäts-Symbol (UML Activity Symbol).\n</li><li>Datenstruktur / Eingangsarray: Byte-Array <code>Data[]</code> (Nutzdaten/Nachrichtenpuffer) ab dem konfigurierbaren Offset <code>Offset</code>.\n</li><li>Zielvariable: Lokale Variable <code>ReceivedDataID</code> vom Datentyp <code>uint32</code>.\n</li><li>Kontrollflusselemente: Startknoten (Initial Node), eine ausführende Aktion (Action) und Endknoten (Activity Final Node).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Ausführung beginnt am initialen Startknoten.\n</li><li>Der Kontrollfluss geht über in die Aktion: Es werden 4 zusammenhängende Bytes aus dem Datenstrom <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Variable <code>ReceivedDataID</code> kopiert.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Ablauf den Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe gemäß <code>[PRS_E2E_00359]</code>: Implementierungen von <code>E2E_P04Check()</code> müssen die DataID exakt an den Bytepositionen <code>Offset + 4</code> bis <code>Offset + 7</code> im Big-Endian-Format deserialisieren.\n</li><li>Entwickler müssen sicherstellen, dass der Puffer <code>Data[]</code> mindestens eine Größe von <code>Offset + 8</code> Bytes aufweist, um Out-of-Bounds-Zugriffe zu vermeiden, und dass plattformabhängige Endianness-Konvertierungen (z. B. auf Little-Endian-Mikrocontrollern) beim Zusammensetzen des 32-Bit-Wertes berücksichtigt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-19d311e0ee2c07d4", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation eines Teilschritts der Prüffunktion <code>E2E_P44Check()</code> innerhalb der AUTOSAR E2E-Bibliothek (E2E Profile 44). Der Kontext umfasst die sicherheitsrelevante End-to-End-Kommunikationsabsicherung auf Empfängerseite, konkret das Auslesen der übertragenen DataID aus dem Nutzdaten-Serialisierungsstrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aufrufende Funktion / Kontext: <code>E2E_P44Check()</code> (gekennzeichnet über das Aktivitäts-/Subaktivitäts-Symbol).\n</li><li>Eingangsdaten / Puffer: Byte-Array <code>Data[]</code> mit anwendungs- bzw. profilkonfiguriertem Versatz <code>Offset</code>.\n</li><li>Lokale Zielvariable: <code>ReceivedDataID</code> vom Datentyp <code>uint32</code>.\n</li><li>Kontrollflusselemente: Initialknoten (Start), Aktionsknoten („Copy bytes...“), Aktivitätsendknoten (Stop).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität startet am Initialknoten beim Eintritt in den Teilschritt „Read DataID“ innerhalb von <code>E2E_P44Check()</code>.\n</li><li>Aus dem Datenarray werden die vier aufeinanderfolgenden Bytes von Index <code>Offset+4</code> bis <code>Offset+7</code> in Big-Endian-Bytereihenfolge gelesen und in die lokale 32-Bit-Variable <code>ReceivedDataID</code> (<code>uint32</code>) kopiert.\n</li><li>Nach erfolgreicher Zuweisung endet der Teilschritt am Aktivitätsendknoten, und der Kontrollfluss wird mit den nachfolgenden Schritten der Profilprüfung (z. B. Validierung gegen die konfigurierte DataID) fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Vorschrift für die Implementierung der Empfängerprüfung in E2E Profile 44: Die DataID belegt exakt 4 Bytes an den relativen Byte-Offsets +4 bis +7 bezogen auf den Basiskonfigurationsparameter <code>Offset</code>.\n</li><li>Die Bytereihenfolge (Endianness) im Datenstrom ist strikt als Big Endian (Most Significant Byte zuerst) vorgeschrieben und muss plattformunabhängig in die Host-Byte-Order der lokalen Variable <code>ReceivedDataID</code> überführt werden.\n</li><li>Entwickler müssen sicherstellen, dass die Gesamtlänge des Puffers <code>Data[]</code> mindestens <code>Offset + 8</code> Bytes beträgt, um Speicherzugriffsverletzungen (Buffer Overflows) beim Lesezugriff zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ca4fadad7ab649f1", "to": "FIG-c16c0f88bb6c223a", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
